      "prompt": "たなか「ああさとうさん。お元気でしたか。」\nさとう「はい。ありがとうございます。さいきん（ア）、きょうはごあいさつに来たんですよ。」\nたなか「そうですか。どんなおしごとですか。」\nさとう「ぼうえきのしごとです。この近くに今のじむしょがあるんですよ。たなかさん、ぜひ一度（イ）。」\nたなか「ありがとうございます。新しいじむしょのじゅうしょはどちらですか。」\nさとう「（ウ）。どうぞ。」\nたなか「どうも。じゃあ来週おじゃましてもいいですか。」\nさとう「（エ）。じゃあそのときにいっしょにお昼を食べませんか。食べながらしごとのことをお話しましょう。」\n\n（ア）",
