      "prompt": "Ａ「来月、先生をおよびして、パーティーをするんですが、どこかいい店を知りませんか。」\nＢ「どんな店がいいんですか。」\nＡ「しずかで、料理がおいしいところがいいんですが。」\nＢ「ねだんが（ア）。」\nＡ「ええ、いいです。」\nＢ「大学の近くにおいしいタイ料理のレストランがありますよ。」\nＡ「でも、タイ料理はからいでしょう。先生は（イ）。」\nＢ「じゃあ、『あおやま』はどうでしょうか。日本料理の店です。広くてしずかで、とてもおいしいです。（ウ）、駅から近いしべんりですよ。」\nＡ「それはいいですね。電話ばんごうを知っていますか。」\nＢ「今はちょっと……。（エ）。」\nＡ「じゃあ、こんばん電話しますから、教えてください。」\n\n（エ）",
