    "meaning": {
      "prompt": "田中さんと りーさんは 友だちです。こんばん、田中さんの 家で パーティーを します。今 二人は 田中さんの 家で 話して います。\n田中「そろそろ パーティーの じゅんびを しましょう。」\nリー「私も てつだいます。みんな 何時ごろ 来るんですか。」\n田中「５時ごろ 来ると 言って いました。」\nリー「はじめに 何を しますか。」\n田中「そうじは 朝 して しまいましたから、花を かざりましょう。さっき友だちに 花を もらったんです。」\nリー「私は 音楽の テープを たくさん 持って きました。みんな どんな音楽が 好きですか。」\n田中「何でも 好きですよ。でも、小林さんは しずかな 音楽が 好きだと思います。にぎやかな 音楽は あまり・・・。」\nリー「そうですか。料理はどうですか。」\n田中「料理は まだ ぜんぜん 作って いません。」\nリー「私の 国の 料理を 作っても いません。」\n田中「いいですね。（４４）。おねがいします。れいぞうこに やさいと 肉が （４５）から、よかったら 使って ください。」\nリー「ありがとう こざいます。」\n\n４５には何を入れますか。",
      "options": [
        "入れてしまいます",
        "入れておきます",
        "入ってみます",
        "入っています"
      ],
      "answerIndex": 3
    },
    "optionExplanations": [
      "「入れてしまいます」意思是「（把菜和肉）放進去」，是未來即將做的動作，與後面「よかったら使ってください（如果你要的話請使用）」所暗示的「已經在那裡」的語境不合，錯誤。",
      "「入れておきます」意思是「先放進去（備用）」，同樣是未來動作，與「使ってください」所需的既有存在狀態不合，錯誤。",
      "「入ってみます」文法不通順（「入る」是自動詞，「〜てみる」通常用於主動嘗試的動作，冰箱裡的菜不會自己嘗試進入），錯誤。",
      "「入っています」表示「（現在）冰箱裡有菜和肉」，陳述既有的存在狀態，田中告訴リーさん冰箱裡已經有材料可以用，語意通順，為正解。"
    ],
