      "prompt": "さとう「今月から 仕事の 時間が 早く なったそうだね。」\nすずき「ええ。でも、朝 仕事の 時間に 間に合わなくて……。」\nさとう「えっ、間に合わない？」\nすずき「（①）。」\nさとう「ふーん、どんな とけい？」\nすずき「大きな 音が 出る 時計です。ベッドの そばに 四つ おきました。」\nさとう「へえ、四つも！ いっしょに 音が 出たら、とても 大きいね。」\nすずき「ええ、妹に（②）と おこられました。わたしも 音は 聞こえるんですが、すぐ 止めて また ねて しまうんです。」\nさとう「そうか。」\nすずき「妹に おこられても いいから、早く 起きたいんです。どうしたら いいでしょうか。」\nさとう「そうだね。まず、時計は（③）ように すると いいよ。たとえば、6時に 起きたかったら 5時50分に。」\nすずき「10分前ですね。」\nさとう「そう。それから、時計を いろいろな 場所に おくと いいよ。四つの時計が ぜんぶ ちがう 場所に あったら、音を 止める ために 起きなければ ならないから。」\nすずき「なるほど！ そうですね。すぐに やって みます。」\n\n（③）には 何を 入れますか。",
