    "meaning": {
      "prompt": "東京の電車\n　シュミット　ダニエル\n\n　東京に来て、電車を使う人がとても多いのにびっくりしました。ラッシュアワは、駅も電車も本当に混雑しています。最初は、人が多くて大変なのに、なぜみんなが電車を使おうとするのが不思議でした。しかし、東京に来て3か月たって、その理由が(19)　。\n\n　まず、東京には、10種類以上の電車が走っていて、電車の駅は600以上あります。たくさん駅があるから、どこへでも行くことができます。(20)、電車が遅れることも少ないし、あまり待たなくてもすぐに次の電車が来ます。実際に、わたしが使っている電車は、ラッシュアワーには3分に1本来ます。(21)なら、みんなが使いたくなる気持ちもわかります。\n\n　しかし、今でもわからないことが一つあります。東京では電車が次々来るから、電車の時間を気にして急ぐ必要はないはずです。ところが、駅の中や階段、ホームを、とても急いで歩いている人が多いです。わたしは、これが(22)わかりません。日本に長く住んでいたら、わたしも同じように(23)。留学生活が終わるころには、答えがわかるのかもしれません。\n\n(20)",
      "options": [
        "したがって",
        "つまり",
        "たとえば",
        "それから"
      ],
      "answerIndex": 3
    },
    "optionExplanations": [
      "「したがって」意為「因此」，表因果關係，與前後句（列舉電車多、車站多等優點）語意不合。",
      "「つまり」意為「總之、也就是說」，用於歸納總結，與此處列舉新的優點不合。",
      "「たとえば」意為「例如」，但此處並非在舉例，而是承接上句繼續補充理由。",
      "正解。「それから」意為「還有、再加上」，用於補充列舉另一個理由（電車誤點少、等車時間短），語意通順。"
    ]
