      "「言わせました」是使役形（讓人說），與句意「被前輩說了」不合。",
      "正解。「言われました」是被動形，句意「学校で先輩に「おはよう。」と言われました」（在學校被前輩說了『早安』），文意通順，且後文以「起きてすぐに来たから、間違えて言ったのだと思いました」呼應「被說」的情境。",
